<script setup>import {Head,Link,usePage} from '@inertiajs/vue3';import AppLayout from '@/Layouts/AppLayout.vue';import Button from '@/Components/UI/Button.vue';import Icon from '@/Components/UI/Icon.vue';defineOptions({layout:AppLayout});defineProps({shifts:[Array,Object],period:Object});const page=usePage();const dt=v=>new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v));</script><template><Head title="Planning à imprimer"/><div class="mx-auto max-w-6xl space-y-3"><div class="print-actions flex justify-between"><Button :as="Link" href="/administration/planning" size="rg" variant="white-outline"><Icon name="arrow-left"/><span class="ms-2">Retour</span></Button><Button size="rg" @click="window.print()"><Icon name="printer"/><span class="ms-2">Imprimer</span></Button></div><article class="print-doc bg-white p-8 text-slate-900"><header class="flex justify-between border-b-2 border-slate-900 pb-4"><div><strong class="uppercase">{{page.props.site?.brand||'Clinique Saint Georges'}}</strong><p class="text-xs">Site {{page.props.site?.name||''}}</p></div><div class="text-end"><h1 class="text-xl font-black uppercase">Planning du personnel</h1><p class="text-xs">Du {{period.from}} au {{period.to}}</p></div></header><table class="mt-8 w-full border-collapse text-xs"><thead><tr><th class="border border-slate-400 p-2 text-start">Employé</th><th class="border border-slate-400 p-2 text-start">Département</th><th class="border border-slate-400 p-2 text-start">Objet</th><th class="border border-slate-400 p-2 text-start">Début</th><th class="border border-slate-400 p-2 text-start">Fin</th></tr></thead><tbody><tr v-for="shift in shifts" :key="shift.uuid"><td class="border border-slate-300 p-2">{{shift.employee.name}}<br>{{shift.employee.employee_number}}</td><td class="border border-slate-300 p-2">{{shift.department||shift.employee.department||'N/R'}}</td><td class="border border-slate-300 p-2">{{shift.title||'—'}}</td><td class="border border-slate-300 p-2">{{dt(shift.starts_at)}}</td><td class="border border-slate-300 p-2">{{dt(shift.ends_at)}}</td></tr></tbody></table></article></div></template><style>@media print{.print-actions,aside,nav{display:none!important}.print-doc{padding:0!important}}</style>
